int fibonacci( int n )
{
printf(“%d∖n”, n);
if ( n == 0 )
return 0;
else if ( n == 1 )
return 1;
else
return ( fibonacci( n - 1 )
+ fibonacci( n - 2 ) );
}

int binarySearch(int *a, int key, int low, int high)
{
int middle;
while (low <= high) {
middle = (low + high) / 2;
if (key == a[middle])
return middle;
else if (key > a[middle])
low = middle + 1;
else
high = middle - 1;
}
return -1;
}

